// 2. Run and watch for errors
await using var run = await InProcessExecution.RunStreamingAsync(workflow, input);
await foreach (var evt in run.WatchStreamAsync())
{
    if (evt is ExecutorFailedEvent failed)
    {
        // 3. On failure: re-run the failed lookup or escalate
        await HandleFailedLookupAsync(failed.ExecutorId, input);
    }
}

// 4. Memory: configure bounded history on each agent
var agent = new ChatClientAgent(chatClient, name: "Researcher",
    instructions: "...",
    chatReducer: new TruncatingChatReducer(maxMessages: 10));

// 5. After workflow: reset state for next run
await context.SendMessageAsync(new ResetChatSignal(), ct);
```

